#!/bin/bash
sed -i 's/val intent = Intent.parseUri(target, Intent.URI_INTENT_SCHEME)/if (target == "share:\/\/prompt") {\n                        val shareIntent = Intent(Intent.ACTION_SEND).apply { type = "text\/plain"; putExtra(Intent.EXTRA_TEXT, "Shared from Flux") }\n                        val chooser = Intent.createChooser(shareIntent, "Share to...").apply { addFlags(Intent.FLAG_ACTIVITY_NEW_TASK) }\n                        context.startActivity(chooser)\n                        return\n                    } else if (target == "note:\/\/new") {\n                        try {\n                           val noteIntent = Intent(Intent.ACTION_SEND).apply { type = "text\/plain"; setPackage("com.google.android.keep"); addFlags(Intent.FLAG_ACTIVITY_NEW_TASK) }\n                           context.startActivity(noteIntent)\n                        } catch(e: Exception) {\n                           Toast.makeText(context, "Note app not found", Toast.LENGTH_SHORT).show()\n                        }\n                        return\n                    }\n                    val intent = Intent.parseUri(target, Intent.URI_INTENT_SCHEME)/g' /app/applet/app/src/main/java/com/example/features/ActionRouter.kt
